import{_ as e,a as r,c as a,ac as d}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Redis设计与实现","description":"按黄健宏版的24章整理数据结构、单机机制、多机机制与独立功能。","frontmatter":{"title":"Redis设计与实现","description":"按黄健宏版的24章整理数据结构、单机机制、多机机制与独立功能。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 编程语言与开发框架","summary":"按黄健宏版的24章整理数据结构、单机机制、多机机制与独立功能。","status":"active","related":[{"title":"C语言程序设计","link":"/life/personal/books/computing/c-programming","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Go语言高并发与微服务实战","link":"/life/personal/books/computing/go-concurrency-microservices","kind":"书籍导读","scope":"general","audience":"general"},{"title":"深入浅出Spring Boot 2.x","link":"/life/personal/books/computing/spring-boot-2","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Rust程序设计（第2版）","link":"/life/personal/books/computing/programming-rust","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"深入浅出Spring Boot 2.x","link":"/life/personal/books/computing/spring-boot-2"},"next":{"text":"Rust程序设计（第2版）","link":"/life/personal/books/computing/programming-rust"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"深入浅出Spring Boot 2.x","link":"/life/personal/books/computing/spring-boot-2"},"next":{"text":"Rust程序设计（第2版）","link":"/life/personal/books/computing/programming-rust"}},"headers":[],"relativePath":"life/personal/books/computing/redis-design.md","filePath":"life/personal/books/computing/redis-design.md"}'),o={name:"life/personal/books/computing/redis-design.md"};function i(n,t,s,l,p,h){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="redis设计与实现" tabindex="-1">Redis设计与实现 <a class="header-anchor" href="#redis设计与实现" aria-label="Permalink to &quot;Redis设计与实现&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 编程语言与开发框架</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>黄健宏的《Redis设计与实现》从数据结构进入数据库运行机制，解释 Redis 命令背后的内存组织、持久化、事件循环、复制与集群。适合已经使用过 Redis、希望理解性能与行为边界的开发者。</p><p>它的主要价值是建立“命令—对象编码—执行流程—持久化或复制”的联系。读者不必一开始就通读全部源码，可以先根据设计图建立结构，再进入对应实现。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>本页采用作者读者服务站列出的 <strong>24 章纸书结构</strong>，配套源码为 Redis 3.0；它不同于作者早期介绍 Redis 2.6 的免费网络原始版。书单未提供 ISBN，实际藏书可据作者和目录再次确认。当前 Redis 的数据结构与复制等细节已有变化，不能把历史实现当作所有版本的事实。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>作者为黄健宏（huangz），其个人主页列有多部 Redis 著作与技术译作；本书读者服务站持续提供目录、试读和注释源码。可以从公开的设计说明、源码对应和勘误核验其专业内容，而不是仅凭“深入底层”的宣传判断。作者网站也明确区分纸书与较早网络原始版。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合已经使用 Redis 字符串、集合或缓存、希望解释内存与执行成本的开发者。需要立即配置新版本集群的人应同时查相应官方文档；没有 C 基础也可先读设计图，但读注释源码时要补指针与内存知识。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><p>以下按原书 24 章逐章概括，介绍文字为本站转述。</p><table tabindex="0"><thead><tr><th>章节</th><th>核心内容</th></tr></thead><tbody><tr><td>第1章 简介</td><td>说明覆盖版本、章节组织和阅读方法，建立阅读源码与阅读设计的关系。</td></tr><tr><td>第2章 简单动态字符串</td><td>解释 SDS 如何记录长度与容量，以及它相对 C 字符串的取舍。</td></tr><tr><td>第3章 链表</td><td>介绍双向链表节点与操作，理解它如何支持灵活的顺序数据访问。</td></tr><tr><td>第4章 字典</td><td>讨论哈希表、冲突处理和渐进式 rehash，观察扩容如何分摊成本。</td></tr><tr><td>第5章 跳跃表</td><td>通过分层链接理解有序查找，以及它在有序集合中的作用。</td></tr><tr><td>第6章 整数集合</td><td>解释紧凑整数存储与编码升级，关注空间节约与升级代价。</td></tr><tr><td>第7章 压缩列表</td><td>分析连续内存编码与连锁更新，理解紧凑表示带来的时间空间权衡。</td></tr><tr><td>第8章 对象</td><td>将逻辑类型与实际编码分开，介绍多态、引用计数和对象共享。</td></tr><tr><td>第9章 数据库</td><td>介绍键空间、过期时间和删除策略，连接持久化与复制中的过期处理。</td></tr><tr><td>第10章 RDB 持久化</td><td>说明快照生成、载入与文件结构，理解恢复所依赖的数据边界。</td></tr><tr><td>第11章 AOF 持久化</td><td>介绍命令追加、刷盘与重写，比较操作记录和数据快照的思路。</td></tr><tr><td>第12章 事件</td><td>区分文件事件和时间事件，解释事件循环如何组织服务执行。</td></tr><tr><td>第13章 客户端</td><td>介绍客户端状态、缓冲区及创建和关闭过程。</td></tr><tr><td>第14章 服务器</td><td>沿命令请求、周期任务和初始化过程串起单机服务器。</td></tr><tr><td>第15章 复制</td><td>比较全量同步与部分重同步，分析复制偏移量和积压缓冲区的作用。</td></tr><tr><td>第16章 Sentinel</td><td>介绍故障判断、领头选举和故障转移，区分主观下线与客观下线。</td></tr><tr><td>第17章 集群</td><td>说明槽分配、重定向、迁移与故障转移，理解数据分布和请求路由。</td></tr><tr><td>第18章 发布与订阅</td><td>分析频道、模式订阅及消息分发的数据结构与流程。</td></tr><tr><td>第19章 事务</td><td>介绍命令入队、执行与 WATCH，讨论事务性质及其边界。</td></tr><tr><td>第20章 Lua 脚本</td><td>解释脚本环境、执行、缓存与复制的实现联系。</td></tr><tr><td>第21章 排序</td><td>分解 SORT 的不同选项，理解一次命令如何组合取值、比较与输出。</td></tr><tr><td>第22章 二进制位数组</td><td>介绍位访问、计数和逻辑运算，连接位表示与算法效率。</td></tr><tr><td>第23章 慢查询日志</td><td>说明慢查询记录的保存和管理，理解它能反映哪一段执行成本。</td></tr><tr><td>第24章 监视器</td><td>介绍 MONITOR 客户端及命令信息分发，理解观察机制本身的工作方式。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>命令只是入口，编码、执行和恢复边界决定它的代价。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>选择一个常用集合，把逻辑操作对应到书中的底层表示，再标出扩容、编码转换或持久化可能引入的额外工作。这样能把“Redis 很快”改成有条件的性能判断，并区分事务、复制和落盘各自解决的问题。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>高层设计图便于建立整体结构，版本久远则限制了细节直接复用。压缩列表、对象编码和复制机制应与书中版本对照，不能把历史名称写成所有版本事实；建议在正在使用的版本上另查实现并验证关键假设。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐给不满足于会用命令的人：从一个实际键的表示出发读设计，源码会更容易找到入口。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li><a href="https://huangz.works/redisbook1e/" target="_blank" rel="noopener noreferrer">作者读者服务站：目录、试读与版本说明</a>：24 章结构的主要来源。</li><li><a href="https://github.com/huangzworks/redis-3.0-annotated" target="_blank" rel="noopener noreferrer">配套 Redis 3.0 注释源码</a>：深入实现时使用。</li><li><a href="https://huangz.works/redisbook/" target="_blank" rel="noopener noreferrer">作者早期网络原始版</a>：用于区分版本，不与纸书目录混用。</li><li><a href="https://huangz.works/" target="_blank" rel="noopener noreferrer">黄健宏个人主页</a>：核对作者、技术写作与翻译方向。</li></ul>',27)])])}const g=e(o,[["render",i]]);export{u as __pageData,g as default};
